// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Session login for the UI (when auth is enabled)
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Clear the session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ListBlocklist Failed releases that will never be re-grabbed
	// (GET /blocklist)
	ListBlocklist(w http.ResponseWriter, r *http.Request)
	// RemoveBlocklistEntry Unblock a release
	// (DELETE /blocklist/{id})
	RemoveBlocklistEntry(w http.ResponseWriter, r *http.Request, id int64)
	// GetCalendar Episodes airing and movies/books released in a date range
	// (GET /calendar)
	GetCalendar(w http.ResponseWriter, r *http.Request, params GetCalendarParams)
	// ListCustomFormats Custom-format scoring rules
	// (GET /customformats)
	ListCustomFormats(w http.ResponseWriter, r *http.Request)
	// AddCustomFormat Add a scoring rule
	// (POST /customformats)
	AddCustomFormat(w http.ResponseWriter, r *http.Request)
	// DeleteCustomFormat Remove a scoring rule
	// (DELETE /customformats/{id})
	DeleteCustomFormat(w http.ResponseWriter, r *http.Request, id int64)
	// ListDownloadClients List download clients
	// (GET /downloadclients)
	ListDownloadClients(w http.ResponseWriter, r *http.Request)
	// AddDownloadClient Add a download client
	// (POST /downloadclients)
	AddDownloadClient(w http.ResponseWriter, r *http.Request)
	// TestDownloadClient Test a download client config
	// (POST /downloadclients/test)
	TestDownloadClient(w http.ResponseWriter, r *http.Request)
	// DeleteDownloadClient Remove a download client
	// (DELETE /downloadclients/{id})
	DeleteDownloadClient(w http.ResponseWriter, r *http.Request, id int64)
	// TestDownloadClientById Test a saved download client with its stored credentials
	// (POST /downloadclients/{id}/test)
	TestDownloadClientById(w http.ResponseWriter, r *http.Request, id int64)
	// StreamEvents Server-sent events
	// (GET /events)
	StreamEvents(w http.ResponseWriter, r *http.Request)
	// GrabRelease Send a release to a download client
	// (POST /grab)
	GrabRelease(w http.ResponseWriter, r *http.Request)
	// GetHealth Run health checks and report results
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListImportLists Import list sources
	// (GET /importlists)
	ListImportLists(w http.ResponseWriter, r *http.Request)
	// AddImportList Add an import list source
	// (POST /importlists)
	AddImportList(w http.ResponseWriter, r *http.Request)
	// DeleteImportList Remove an import list source
	// (DELETE /importlists/{id})
	DeleteImportList(w http.ResponseWriter, r *http.Request, id int64)
	// ListIndexers List indexers
	// (GET /indexers)
	ListIndexers(w http.ResponseWriter, r *http.Request)
	// AddIndexer Add an indexer
	// (POST /indexers)
	AddIndexer(w http.ResponseWriter, r *http.Request)
	// TestIndexer Test an indexer config (t=caps)
	// (POST /indexers/test)
	TestIndexer(w http.ResponseWriter, r *http.Request)
	// DeleteIndexer Remove an indexer
	// (DELETE /indexers/{id})
	DeleteIndexer(w http.ResponseWriter, r *http.Request, id int64)
	// TestIndexerById Test a saved indexer with its stored credentials
	// (POST /indexers/{id}/test)
	TestIndexerById(w http.ResponseWriter, r *http.Request, id int64)
	// ListLibrary List library items
	// (GET /library)
	ListLibrary(w http.ResponseWriter, r *http.Request, params ListLibraryParams)
	// AddLibraryItem Add a media item (hydrates metadata from the provider)
	// (POST /library)
	AddLibraryItem(w http.ResponseWriter, r *http.Request)
	// BulkEditLibrary Apply monitoring/profile changes to many items at once
	// (POST /library/bulk)
	BulkEditLibrary(w http.ResponseWriter, r *http.Request)
	// ScanLibrary Trigger a disk scan / reconcile
	// (POST /library/scan)
	ScanLibrary(w http.ResponseWriter, r *http.Request)
	// GetScanReport Result of the most recent scan
	// (GET /library/scan/report)
	GetScanReport(w http.ResponseWriter, r *http.Request)
	// DeleteLibraryItem Remove an item from the library (files on disk are untouched)
	// (DELETE /library/{id})
	DeleteLibraryItem(w http.ResponseWriter, r *http.Request, id int64)
	// GetLibraryItem Get one item with seasons, episodes, and files
	// (GET /library/{id})
	GetLibraryItem(w http.ResponseWriter, r *http.Request, id int64)
	// UpdateLibraryItem Edit an item's monitoring, quality profile, or location
	// (PATCH /library/{id})
	UpdateLibraryItem(w http.ResponseWriter, r *http.Request, id int64)
	// AutoSearchLibraryItem Search for everything this item wants and grab the best releases
	// (POST /library/{id}/autosearch)
	AutoSearchLibraryItem(w http.ResponseWriter, r *http.Request, id int64)
	// AddMediaCopy Add an additional quality copy (e.g. a 720p copy of a 4K item)
	// (POST /library/{id}/copies)
	AddMediaCopy(w http.ResponseWriter, r *http.Request, id int64)
	// DeleteMediaCopy Remove a copy (its files on disk are kept)
	// (DELETE /library/{id}/copies/{copyId})
	DeleteMediaCopy(w http.ResponseWriter, r *http.Request, id int64, copyId int64)
	// UpdateMediaCopy Edit a copy's name, profile, or monitoring
	// (PATCH /library/{id}/copies/{copyId})
	UpdateMediaCopy(w http.ResponseWriter, r *http.Request, id int64, copyId int64)
	// SetEpisodeMonitored Monitor or unmonitor one episode
	// (PATCH /library/{id}/episodes/{episodeId})
	SetEpisodeMonitored(w http.ResponseWriter, r *http.Request, id int64, episodeId int64)
	// RefreshLibraryItem Re-hydrate this item's metadata from its provider
	// (POST /library/{id}/refresh)
	RefreshLibraryItem(w http.ResponseWriter, r *http.Request, id int64)
	// SearchReleases Interactive search for a movie, episode, or season pack
	// (GET /library/{id}/releases)
	SearchReleases(w http.ResponseWriter, r *http.Request, id int64, params SearchReleasesParams)
	// SetSeasonMonitored Monitor or unmonitor one season (cascades to its episodes)
	// (PATCH /library/{id}/seasons/{season})
	SetSeasonMonitored(w http.ResponseWriter, r *http.Request, id int64, season int)
	// SearchMetadata Search the metadata provider
	// (GET /metadata/search)
	SearchMetadata(w http.ResponseWriter, r *http.Request, params SearchMetadataParams)
	// ListNotifiers List notification targets
	// (GET /notifiers)
	ListNotifiers(w http.ResponseWriter, r *http.Request)
	// AddNotifier Add a notification target
	// (POST /notifiers)
	AddNotifier(w http.ResponseWriter, r *http.Request)
	// TestNotifier Send a test notification with an unsaved config
	// (POST /notifiers/test)
	TestNotifier(w http.ResponseWriter, r *http.Request)
	// DeleteNotifier Remove a notification target
	// (DELETE /notifiers/{id})
	DeleteNotifier(w http.ResponseWriter, r *http.Request, id int64)
	// ListProfiles List quality profiles
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// ListQueue Recent downloads (all states)
	// (GET /queue)
	ListQueue(w http.ResponseWriter, r *http.Request)
	// RemoveQueueItem Remove a queue row (optionally from the client too)
	// (DELETE /queue/{id})
	RemoveQueueItem(w http.ResponseWriter, r *http.Request, id int64, params RemoveQueueItemParams)
	// ListRootFolders List library root folders
	// (GET /rootfolders)
	ListRootFolders(w http.ResponseWriter, r *http.Request)
	// AddRootFolder Register a library root folder
	// (POST /rootfolders)
	AddRootFolder(w http.ResponseWriter, r *http.Request)
	// DeleteRootFolder Remove a root folder registration (disk untouched)
	// (DELETE /rootfolders/{id})
	DeleteRootFolder(w http.ResponseWriter, r *http.Request, id int64)
	// GetSettings Read settings (secrets masked)
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Update settings
	// (PUT /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// ListBackups On-disk database backups (newest first)
	// (GET /system/backups)
	ListBackups(w http.ResponseWriter, r *http.Request)
	// GetSystemStatus System status
	// (GET /system/status)
	GetSystemStatus(w http.ResponseWriter, r *http.Request)
	// ListTasks Scheduler task states
	// (GET /system/tasks)
	ListTasks(w http.ResponseWriter, r *http.Request)
	// RunTask Trigger an immediate run of a scheduled task
	// (POST /system/tasks/{name}/run)
	RunTask(w http.ResponseWriter, r *http.Request, name string)
	// ListWanted Everything still wanted (missing or below cutoff)
	// (GET /wanted)
	ListWanted(w http.ResponseWriter, r *http.Request)
}

